describe("Cart — totals pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("empty cart has zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.10 }),
      region: "US",
    });
    cart.add(widget, 10); // subtotal = 10000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000); // 10%
    // Tax on discounted subtotal: 10% of 9000 = 900
    expect(t.taxCents).toBe(900);
    expect(t.shippingCents).toBe(0); // default free
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("clamps discount to [0, subtotal]", () => {
    // A policy that returns more than subtotal
    const overDiscount = { computeDiscountCents: () => 999999 };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(widget, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount = { computeDiscountCents: () => -500 };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.subtotalCents).toBe(1000);
  });

  it("includes shipping in total", () => {
    const cart = new Cart({
      shippingCalculator: new FlatShippingCalculator(500),
    });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(1000 + 500);
  });

  it("shipping receives discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
      shippingCalculator: new FlatShippingCalculator(999, 600),
    });
    cart.add(widget, 1); // subtotal 1000, discount 500, discounted 500
    const t = cart.totals();
    // discountedSubtotal (500) < freeOverCents (600) → flat fee charged
    expect(t.shippingCents).toBe(999);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax = { computeTaxCents: () => -100 };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping = { computeShippingCents: () => -100 };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses defaults when no config provided", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const t = cart.totals();
    // Default: NoDiscount, NoTax, FreeShipping
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });
});

describe("Cart — async checkout", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(3000);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("throws InventoryError on denial (available: false)", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      region: "US",
    });
    cart.add(widget, 10); // subtotal = 10000, discount = 1000, taxable = 9000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.discountCents).toBe(1000);
    // 8% of 9000 = 720
    expect(result.totals.taxCents).toBe(720);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "FR",
    });
    cart.add(widget, 2);
    cart.add(gadget, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200)  // widget
        .mockResolvedValueOnce(2500), // gadget
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal: 1200*2 + 2500*1 = 4900
    expect(result.totals.subtotalCents).toBe(4900);
    expect(result.totals.discountCents).toBe(0);
    // tax: 20% of 4900 = 980
    expect(result.totals.taxCents).toBe(980);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(4900 + 980 + 500);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("generates default InventoryError message with quantities", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      const err = e as InventoryError;
      expect(err.message).toContain("w");
      expect(err.message).toContain("5");
      expect(err.message).toContain("2");
    }
  });

  it("checks inventory for each line and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "gadget gone" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("g");
      expect(err.message).toBe("gadget gone");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 99999])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to the nearest cent", () => {
      // 10% of 999 = 99.9 → floors to 99
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(999)).toBe(99);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("0% yields no discount", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("100% yields full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("handles large subtotal correctly", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 1_000_000 = 150_000
      expect(policy.computeDiscountCents(1_000_000)).toBe(150_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts in sum mode = 120% of subtotal
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(60), new PercentageDiscountPolicy(60)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining = 900
      // Second: 10% of 900 = 90, remaining = 810
      // Total discount = 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step at remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0
      // Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      // Fixed 500 first, then 10% of remainder
      const ab = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 500 off 1000 → remaining 500, 10% of 500 = 50, total = 550
      expect(ab.computeDiscountCents(1000)).toBe(550);

      // 10% first, then fixed 500
      const ba = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900, min(500,900)=500, total = 600
      expect(ba.computeDiscountCents(1000)).toBe(600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // max(0, -100) clamped via min(max(0,-100), 1000) = 0 → remaining 1000
      // then min(200, 1000) = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum when mode is not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

