import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });

  it("is an instance of Error", () => {
    const err = new InventoryError("msg", "p", 1, 0);
    expect(err).toBeInstanceOf(Error);
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "a", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "b", name: "Gadget", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("updates each line with fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves product fields other than unitPriceCents", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices(
      [{ product: { id: "x", name: "X", unitPriceCents: 1, weightGrams: 500 }, quantity: 1 }],
      fetcher,
    );
    expect(result[0]!.product.name).toBe("X");
    expect(result[0]!.product.weightGrams).toBe(500);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("service down");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import {
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  NoDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator, NoTaxCalculator } from "../src/tax.ts";
import {
  FlatShippingCalculator,
  FreeShippingCalculator,
} from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const widget: Product = { id: "w", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g", name: "Gadget", unitPriceCents: 2000 };

describe("Cart — line management", () => {
  it("adds a product and reflects in itemCount", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantity when adding the same product twice", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity in add", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity in add", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "b", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove("w")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.updateQuantity("w", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the item", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nope", 1)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const snap = cart.snapshot();
    // Mutating snapshot should not affect cart internals
    (snap[0] as { quantity: number }).quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — totals pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("empty cart has zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.10 }),
      region: "US",
    });
    cart.add(widget, 10); // subtotal = 10000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000); // 10%
    // Tax on discounted subtotal: 10% of 9000 = 900
    expect(t.taxCents).toBe(900);
    expect(t.shippingCents).toBe(0); // default free
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("clamps discount to [0, subtotal]", () => {
    // A policy that returns more than subtotal
    const overDiscount = { computeDiscountCents: () => 999999 };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(widget, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount = { computeDiscountCents: () => -500 };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.subtotalCents).toBe(1000);
  });

  it("includes shipping in total", () => {
    const cart = new Cart({
      shippingCalculator: new FlatShippingCalculator(500),
    });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(1000 + 500);
  });

  it("shipping receives discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
      shippingCalculator: new FlatShippingCalculator(999, 600),
    });
    cart.add(widget, 1); // subtotal 1000, discount 500, discounted 500
    const t = cart.totals();
    // discountedSubtotal (500) < freeOverCents (600) → flat fee charged
    expect(t.shippingCents).toBe(999);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax = { computeTaxCents: () => -100 };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping = { computeShippingCents: () => -100 };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses defaults when no config provided", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const t = cart.totals();
    // Default: NoDiscount, NoTax, FreeShipping
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });
});

describe("Cart — async checkout", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(3000);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("throws InventoryError on denial (available: false)", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      region: "US",
    });
    cart.add(widget, 10); // subtotal = 10000, discount = 1000, taxable = 9000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.discountCents).toBe(1000);
    // 8% of 9000 = 720
    expect(result.totals.taxCents).toBe(720);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "FR",
    });
    cart.add(widget, 2);
    cart.add(gadget, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200)  // widget
        .mockResolvedValueOnce(2500), // gadget
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal: 1200*2 + 2500*1 = 4900
    expect(result.totals.subtotalCents).toBe(4900);
    expect(result.totals.discountCents).toBe(0);
    // tax: 20% of 4900 = 980
    expect(result.totals.taxCents).toBe(980);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(4900 + 980 + 500);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("generates default InventoryError message with quantities", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      const err = e as InventoryError;
      expect(err.message).toContain("w");
      expect(err.message).toContain("5");
      expect(err.message).toContain("2");
    }
  });

  it("checks inventory for each line and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "gadget gone" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("g");
      expect(err.message).toBe("gadget gone");
    }
  });
});

