  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts in sum mode = 120% of subtotal
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(60), new PercentageDiscountPolicy(60)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100, remaining = 900
      // Second: 10% of 900 = 90, remaining = 810
      // Total discount = 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step at remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0
      // Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      // Fixed 500 first, then 10% of remainder
      const ab = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 500 off 1000 → remaining 500, 10% of 500 = 50, total = 550
      expect(ab.computeDiscountCents(1000)).toBe(550);

      // 10% first, then fixed 500
      const ba = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900, min(500,900)=500, total = 600
      expect(ba.computeDiscountCents(1000)).toBe(600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // max(0, -100) clamped via min(max(0,-100), 1000) = 0 → remaining 1000
      // then min(200, 1000) = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum when mode is not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});
