    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const snap = cart.snapshot();
    // Mutating snapshot should not affect cart internals
    (snap[0] as { quantity: number }).quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — totals pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("empty cart has zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.10 }),
      region: "US",
    });
    cart.add(widget, 10); // subtotal = 10000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000); // 10%
    // Tax on discounted subtotal: 10% of 9000 = 900
    expect(t.taxCents).toBe(900);
    expect(t.shippingCents).toBe(0); // default free
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("clamps discount to [0, subtotal]", () => {
    // A policy that returns more than subtotal
    const overDiscount = { computeDiscountCents: () => 999999 };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(widget, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount = { computeDiscountCents: () => -500 };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.subtotalCents).toBe(1000);
  });

  it("includes shipping in total", () => {
    const cart = new Cart({
      shippingCalculator: new FlatShippingCalculator(500),
    });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(1000 + 500);
  });

  it("shipping receives discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
      shippingCalculator: new FlatShippingCalculator(999, 600),
    });
    cart.add(widget, 1); // subtotal 1000, discount 500, discounted 500
    const t = cart.totals();
    // discountedSubtotal (500) < freeOverCents (600) → flat fee charged
    expect(t.shippingCents).toBe(999);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax = { computeTaxCents: () => -100 };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping = { computeShippingCents: () => -100 };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses defaults when no config provided", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const t = cart.totals();
    // Default: NoDiscount, NoTax, FreeShipping
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });
});

describe("Cart — async checkout", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(3000);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("throws InventoryError on denial (available: false)", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
