+      expect(calc.computeShippingCents(singleLine, 4999)).toBe(599);
+    });
+
+    it("charges flat fee when freeOverCents is undefined", () => {
+      const calc = new FlatShippingCalculator(599);
+      expect(calc.computeShippingCents(singleLine, 100_000)).toBe(599);
+    });
+  });
+});
