+describe("WeightBasedShippingCalculator", () => {
+  describe("constructor validation", () => {
+    it("rejects empty brackets array", () => {
+      expect(() => new WeightBasedShippingCalculator([])).toThrow(
+        "at least one weight bracket is required",
+      );
+    });
+
+    it("rejects bracket with non-positive upToGrams", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects bracket with negative costCents", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer upToGrams", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer costCents", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 1.5 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects negative overflowCostCents", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator(
+            [{ upToGrams: 500, costCents: 100 }],
+            -1,
+          ),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer overflowCostCents", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator(
+            [{ upToGrams: 500, costCents: 100 }],
+            10.5,
+          ),
+      ).toThrow(RangeError);
+    });
+  });
+
+  describe("computeShippingCents", () => {
+    const brackets = [
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 2000, costCents: 700 },
+      { upToGrams: 5000, costCents: 1200 },
+    ];
+
+    it("returns 0 for empty cart", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(calc.computeShippingCents([], 5000)).toBe(0);
+    });
+
+    it("returns 0 for zero-weight items", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      const lines: CartLine[] = [
+        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
+      ];
+      expect(calc.computeShippingCents(lines, 300)).toBe(0);
+    });
+
+    it("selects the first bracket whose upToGrams >= weight", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 500g exactly → first bracket
+      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
+    });
+
+    it("selects the next bracket when weight exceeds boundary", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 501g → second bracket
+      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(700);
+    });
+
+    it("selects highest bracket at boundary", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 2000g exactly → second bracket
+      expect(calc.computeShippingCents([makeLine("a", 2000, 1)], 1000)).toBe(700);
+    });
+
+    it("sums weight across multiple lines", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 300*2 + 500*1 = 1100g → second bracket (upTo 2000)
+      const lines: CartLine[] = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
+      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
+    });
+
+    it("sorts brackets regardless of input order", () => {
+      const unordered = [
+        { upToGrams: 5000, costCents: 1200 },
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 2000, costCents: 700 },
+      ];
+      const calc = new WeightBasedShippingCalculator(unordered);
+      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
+    });
+
+    it("uses overflow cost when weight exceeds all brackets", () => {
+      const calc = new WeightBasedShippingCalculator(brackets, 2000);
+      // 6000g > 5000 → overflow
+      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 1000)).toBe(2000);
+    });
+
+    it("falls back to heaviest bracket cost when no overflow defined", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      expect(calc.computeShippingCents([makeLine("a", 10000, 1)], 1000)).toBe(1200);
+    });
+  });
+});
